            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow-x: hidden;
            background-color: black;
            scroll-behavior: smooth;
        }.sc-tw main,.sc-tw nav,.sc-tw footer{
            position: relative;
            z-index: 10;
