            transition: color 0.3s ease;
        }.sc-tw .nav-link:hover{
            color: rgba(255, 255, 255, 1);
        }.sc-tw .nav-link::after{
            content: '';
            position: absolute;
            bottom: -4px;
            left: 0;
            width: 100%;
            height: 1px;
            background: white;
            transform: scaleX(0);
            transform-origin: right;
            transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1);
        }.sc-tw .nav-link:hover::after{
            transform: scaleX(1);
            transform-origin: left;
        }.sc-tw .kinetic-element{
            will-change: transform, opacity;
        }.sc-tw .reveal-up{
            opacity: 0;
